function mktPartners(){const f=st.pf||'';return '<button class="btn big" onclick="ag.ptform()" style="margin:0 0 10px">+ Add partner / referral contact</button><select onchange="st.pf=this.value;render()"><option value="">All types</option>'+PTYPES.map(t=>'<option'+(f==t?' selected':'')+'>'+E(t)+'</option>').join('')+'</select>'
 +(db.PT.filter(p=>!f||p.cat==f).sort((a,b)=>a.name.localeCompare(b.name)).map(p=>itm('ag.ptopen('+p.id+')',E(p.name),E([p.org,p.role].filter(Boolean).join(' · '))+' · '+E(p.cat),p.tel?'📞':'')).join('')||'<div class="empty">No contacts yet.<br><small>Good ones to add: District Production / Agricultural Officer, District Veterinary Officer, nearest research station, seed company representative, local SACCO or bank, insurance agent, radio station, transporter.</small><button class="btn" onclick="ag.ptseed()">Add these as blank contacts</button></div>')}
ag.ptseed=()=>{[['District Production / Agricultural Officer',PTYPES[0]],['District Veterinary Officer',PTYPES[0]],['Nearest research station / extension officer',PTYPES[1]],['Seed company representative',PTYPES[6]],['Local SACCO / bank',PTYPES[3]],['Insurance agent',PTYPES[4]],['Radio station (farmer programmes)',PTYPES[8]],['Transporter',PTYPES[7]]].forEach(([n,c])=>db.PT.push({id:id(),name:n,cat:c,org:'',role:'',tel:'',note:''}));save();render()};
