ag.ptopen=i=>{const p=db.PT.find(x=>x.id==i);modal('<h2>'+E(p.name)+'</h2><small>'+E([p.org,p.role,p.cat].filter(Boolean).join(' · '))+'</small><div style="margin-top:8px">'+kv('Notes',E(p.note))+'</div>'+(p.tel?contact(p.tel):'<small>No phone saved</small>')+'<button class="btn" onclick="modal();ag.ptform('+p.id+')">Edit</button>'+closeBtn)};

/* =====================  GUIDE / CALENDAR  ===================== */
const GSEG=[['crops','Crops'],['live','Livestock'],['prob','Problem finder'],['safe','Safe use'],['cal','Calendar']];
ag.guide=k=>{st.gs=k;st.tab='guide';render();$('#mn').scrollTop=0};
ag.gs=k=>ag.guide(k);
function vGuide(){const s=st.gs||'crops';return '<h2>Crop & livestock guide</h2><small>Typical figures for Uganda. Rates change with soil, variety and rainfall — always follow the seed pack, the product label and the advice of your district agricultural / veterinary officer.</small><div style="height:8px"></div>'+seg(GSEG,s,'ag.gs','sm')+({crops:gCrops,live:gLive,prob:gProb,safe:gSafe,cal:gCal}[s]||gCrops)()}
function gCrops(){return AS.CROPS.map(c=>'<details><summary>'+c.ic+' '+E(c.n)+' <small>· '+E(c.mat)+'</small></summary><div>'+kv('When to plant',E(c.time))+kv('Spacing',E(c.sp))+kv('Seed / planting material',E(c.seed))+kv('Fertilizer',E(c.fert))+kv('Main problems',E(c.pest))+kv('Good practice',E(c.tips))+'<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px">'+c.inp.map(k=>'<button class="chip ok" onclick="ag.findCat(\''+k.replace(/'/g,"\\'")+'\')">'+E(k)+'</button>').join('')+'</div><button class="btn" onclick="ag.vform(0,0,{crop:\''+c.n.replace(/'/g,"\\'")+'\'})">+ Advice visit for '+E(c.n)+'</button></div></details>').join('')}
function gLive(){return AS.LIVESTOCK.map(l=>'<details><summary>'+l.ic+' '+E(l.n)+'</summary><ul>'+l.pts.map(x=>'<li style="margin-bottom:6px">'+E(x)+'</li>').join('')+'</ul></details>').join('')+'<h3>Typical poultry vaccination schedule</h3><div class="tw"><table><tr><th>When</th><th>What</th></tr>'+AS.POULTRY_SCHED.map(r=>'<tr><td>'+E(r[0])+'</td><td style="white-space:normal;text-align:left">'+E(r[1])+'</td></tr>').join('')+'</table></div><small>Programmes differ by area and disease risk. Confirm with a veterinarian. Keep vaccines at 2–8 °C and never sell expired vaccine.</small>'}
function gProb(){return '<input id="gpq" placeholder="Search a problem, crop or symptom…" value="'+E(st.gpq||'')+'" oninput="st.gpq=this.value;ag.plist2()"><div id="gpl"></div>'}
ag.plist2=()=>{const el=$('#gpl');if(!el)return;const w=tok(st.gpq);el.innerHTML=AS.PROBLEMS.filter(p=>hit(w,[p.n,p.kind,p.crops,p.signs].join(' '))).map(p=>'<details><summary>'+E(p.n)+' '+chip(p.kind,p.kind=='Animal'?'gold':p.kind=='Disease'?'bad':'ok')+' <small>'+E(p.crops)+'</small></summary><div>'+kv('Signs',E(p.signs))+kv('What to do',E(p.act))+'<div style="display:flex;flex-wrap:wrap;gap:6px;margin-top:8px">'+p.cat.map(k=>'<button class="chip ok" onclick="ag.findCat(\''+k.replace(/'/g,"\\'")+'\')">'+E(k)+'</button>').join('')+'</div><button class="btn" onclick="ag.vform(0,0,{crop:\''+p.crops.split(',')[0].replace(/'/g,"\\'")+'\',prob:\''+({Pest:'Pests',Disease:'Disease',Weed:'Weeds',Nutrient:'Soil fertility / nutrients',Animal:'Livestock disease'}[p.kind])+'\',find:\'Suspected: '+p.n.replace(/'/g,"\\'")+'\'})">Start an advice visit</button><small>Always confirm the diagnosis in the field. Notifiable animal diseases must be reported to the district veterinary office.</small></div></details>').join('')||empty('No match')};
function gSafe(){return '<div class="tip"><b>Safe, legal agro-input retail</b><small>You are the last link between the chemical and the farmer. Good advice at the counter prevents poisoning, crop loss and residues in food.</small></div>'+AS.SAFE.map(x=>'<details><summary>'+E(x[0])+'</summary><div>'+E(x[1])+'</div></details>').join('')}
const MN=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
function gCal(){const z=db.zone=='no'?'no':'bi',cur=new Date().getMonth()+1;
 const rows=AS.CAL.map(c=>{const pl=c[z]||[],hv=new Set(pl.map(m=>((m-1+Math.round(c.dur))%12)+1));return '<tr><td>'+E(c.n)+'</td>'+MN.map((_,k)=>{const m=k+1,P_=pl.includes(m),H_=hv.has(m)&&!P_;return '<td class="'+(P_?'p':H_?'h':'')+(m==cur?' cur':'')+'">'+(P_?'P':H_?'H':'')+'</td>'}).join('')+'</tr>'}).join('');
 return '<label>Region</label><select onchange="db.zone=this.value;save();render()"><option value="bi"'+(z=='bi'?' selected':'')+'>Two rainy seasons (central, east, south-west)</option><option value="no"'+(z=='no'?' selected':'')+'>Northern / West Nile</option></select><div class="tip"><b>'+MN[cur-1]+': what to focus on</b><small>'+E(AS.MONTH_TIPS[z][cur-1])+'</small></div><div class="tw"><table class="cal"><tr><th>Crop</th>'+MN.map((m,k)=>'<th class="'+(k+1==cur?'cur':'')+'">'+m[0]+'</th>').join('')+'</tr>'+rows+'</table></div><small><b>P</b> = planting window, <b>H</b> = expected harvest. Rains vary from year to year: confirm with your district agricultural office and local weather advice.</small><h3>Month by month for the shop</h3>'+AS.MONTH_TIPS[z].map((t,k)=>'<div class="item" style="cursor:default"><span class="nm"><b>'+MN[k]+'</b><small>'+E(t)+'</small></span></div>').join('')}

